"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[610],{6963:e=>{e.exports=JSON.parse('{"functions":[{"name":"get","desc":"Returns the current value without yielding.\\n\\nOn the client, errors if the value hasn\'t arrived yet. Call [Sencha.waitForReplicators] while loading, or use\\n[TemporaryPlayerReplicator:getAsync] or [TemporaryPlayerReplicator:observe] in code that may run earlier.","params":[{"name":"player","desc":"required on the server, left out on the client","lua_type":"Player?"}],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","source":{"line":155,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"getAsync","desc":"Returns the current value, yielding until it\'s available. Server values always exist, so this only yields on the\\nclient.","params":[{"name":"player","desc":"required on the server, left out on the client","lua_type":"Player?"}],"returns":[{"desc":"","lua_type":"T"}],"function_type":"method","yields":true,"source":{"line":175,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"set","desc":"Sets a player\'s value and sends it to them. Errors if the value doesn\'t match the replicator\'s type. Setting\\na primitive to the value it already has does nothing; setting a table always counts as a change.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"value","desc":"","lua_type":"T"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":195,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"tryUpdate","desc":"Calls `callback` with a player\'s current value. If it returns `true` and a new value, the value is set as with\\n[TemporaryPlayerReplicator:set]; if it returns `false`, nothing changes. Returns what `callback` returned first.\\n\\n`callback` must not yield, so nothing else can change the value between reading and setting it.\\n\\n```lua\\nlocal didBuy = CurrencyNetwork.coinsReplicator:tryUpdate(player, function(coins)\\n\\tif coins < 10 then\\n\\t\\treturn false\\n\\tend\\n\\treturn true, coins - 10\\nend)\\n```","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"callback","desc":"","lua_type":"(value: T) -> (boolean, T?)"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Server"],"source":{"line":223,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"applyIncrementalUpdate","desc":"Applies `patch` to a player\'s value with the incremental config\'s `apply`, then sends only the patch to them.\\nErrors if the patch or the new value doesn\'t match its type, or if the replicator has no incremental config. An\\nempty table patch does nothing.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"patch","desc":"","lua_type":"P"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":250,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"onChanged","desc":"Calls `callback` when the value changes, not for the initial value. On the server this fires for any player whose\\nvalue changes; on the client `player` is always the local player.\\n\\nOn the server, the change is sent to clients before `callback` runs, so anything it changes in response reaches\\nclients after the change that caused it.","params":[{"name":"callback","desc":"","lua_type":"(player: Player, newValue: T, oldValue: T) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","source":{"line":298,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"observe","desc":"Calls `callback` with the current value right away if it has arrived (otherwise when it arrives), then on\\nevery change. `oldValue` is the value before the change, or `nil` for the first call.\\n\\n```lua\\nCurrencyNetwork.coinsReplicator:observe(function(coins, oldCoins)\\n\\tprint(`coins: {oldCoins} -> {coins}`) -- oldCoins is nil the first time\\nend)\\n```","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T?) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":332,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"onUpdateReceived","desc":"Calls `callback` for each patch received, after the value is updated. Only replicators with an incremental\\nconfig receive patches; calling this on one without errors.\\n\\nWhole values (the first value, or a `set`) don\'t fire this; use\\n[TemporaryPlayerReplicator:onChanged] to see every change.","params":[{"name":"callback","desc":"","lua_type":"(newValue: T, oldValue: T, patch: P) -> ()"}],"returns":[{"desc":"","lua_type":"Disconnect"}],"function_type":"method","realm":["Client"],"source":{"line":354,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"getObservable","desc":"Returns an [ObservableValue](https://jdevon.github.io/observable-value/) that follows the replicated value,\\nfor code that works with ObservableValues, like the\\n[ReactObservableValue](https://github.com/JDevon/react-observable-value) hooks. Calling this again returns the same\\none. Setting it doesn\'t change the replicated value. Errors if the value hasn\'t arrived yet.\\n\\n```lua\\nlocal coins = ReactObservableValue.useObservableValue(CurrencyNetwork.coinsReplicator:getObservable())\\n```","params":[],"returns":[{"desc":"","lua_type":"ObservableValue<T>"}],"function_type":"method","realm":["Client"],"source":{"line":378,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}},{"name":"isLoaded","desc":"Returns whether the value has arrived from the server.","params":[],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","realm":["Client"],"source":{"line":394,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}}],"properties":[],"types":[],"name":"TemporaryPlayerReplicator","desc":"One value per player that the server keeps in memory, created with `Sencha.temporaryReplicator.player`. Each\\nplayer\'s value is sent only to that player, starts as the default value, and is cleared when they leave.","source":{"line":24,"path":"src/Replication/Kinds/TemporaryReplicator/TemporaryPlayerReplicator.luau"}}')}}]);